/** Pegasus brand: the gold winged-horse emblem (generated by `pegasus marketing brand`) + Cinzel wordmark. */
export function PegasusMark({ size = 32, className = "" }: { size?: number; className?: string }) {
  return (
    <img src="/static/brand/pegasus-mark.svg" alt="" aria-hidden="true" width={size} height={Math.round(size * 480 / 448)}
         className={className} draggable={false} />
  );
}

export function Logo({ size = 30, withWord = true }: { size?: number; withWord?: boolean }) {
  return (
    <span className="inline-flex items-center gap-2 select-none">
      <PegasusMark size={size} />
      {withWord && <span className="font-brand text-lg font-semibold tracking-[0.08em] gold-text">PEGASUS</span>}
    </span>
  );
}
